-- BullPen Academy — course: "Reading Financial Statements" (intermediate, Pro)
-- Hand-authored + Zod-validated (scripts/_author_phase2.ts). Re-runnable: ON CONFLICT DO NOTHING.

INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('financial-statements', 'Reading Financial Statements', 'Behind every stock are three reports: the income statement, the balance sheet, and the cash flow statement. Learn to read all three — and tell a financially healthy company from a fragile one.', 'FileText', 'violet', 9, 'intermediate', TRUE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'financial-statements'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('the-three-statements', 'The Three Statements', 'read', 0, 10, '{"sections":[{"text":"Every public company publishes three financial statements, and together they tell the whole story of the business. The trick is to think of them as three different questions about the same company — each one answering something the others can’t.","highlightedTerms":[]},{"text":"The income statement answers “did it make money?” It runs over a period of time — a quarter or a year — starting with Revenue at the top and working down to profit at the bottom. It’s the report people quote when they talk about a company “beating earnings.”","highlightedTerms":[{"term":"Revenue","definition":"All money the company earned from selling products or services — before any costs are subtracted."}]},{"text":"The balance sheet answers “what does it own, and what does it owe?” Unlike the income statement, it’s a snapshot at a single moment — a photograph of the company’s Total Assets on one side and its debts on the other.","highlightedTerms":[{"term":"Total Assets","definition":"The total value of everything the company owns — cash, buildings, equipment, intellectual property, and more."}]},{"text":"The cash flow statement answers “where did the cash actually go?” It exists because profit on paper and cash in the bank are not the same thing — and Operating Cash Flow tracks the real money moving in and out of the business.","highlightedTerms":[{"term":"Operating Cash Flow","definition":"Actual cash generated by the company''s core operations. Often considered more reliable than net income because it''s harder to manipulate."}]}],"funFact":"The three statements are linked: net income from the income statement flows into equity on the balance sheet and is the starting line of the cash flow statement. Nudge one and the others move."}'::jsonb),
  ('the-income-statement', 'The Income Statement', 'read', 1, 10, '{"sections":[{"text":"The income statement reads top to bottom like a waterfall. It begins with Revenue — every dollar of sales in the period — and then subtracts costs in stages until what’s left is profit. Following that descent is the whole skill.","highlightedTerms":[{"term":"Revenue","definition":"All money the company earned from selling products or services — before any costs are subtracted."}]},{"text":"First, subtract the direct cost of making the product to get Gross Profit. Divide that by revenue and you have gross margin — how much survives after the basic cost of the goods themselves. A high gross margin means the core product is inherently profitable.","highlightedTerms":[{"term":"Gross Profit","definition":"Revenue minus the direct cost of making the product or service. Higher gross profit means more room to cover other expenses."}]},{"text":"Keep subtracting the costs of running the business — salaries, research, marketing — and you reach Operating Income: profit from the core operation, before interest and taxes. This is often the cleanest read on whether the actual business works.","highlightedTerms":[{"term":"Operating Income","definition":"Profit after deducting operating expenses like salaries and rent — but before taxes and interest. Shows how well the core business runs."}]},{"text":"Finally, take out interest on debt and taxes, and you land on Net Income — the bottom line. Watching the margin shrink at each step shows you exactly where a company makes its money, and where it leaks away.","highlightedTerms":[{"term":"Net Income","definition":"The final profit after every cost — taxes, interest, and all other expenses — has been subtracted. The \"bottom line.\""}]}],"funFact":"A company can have a fat gross margin but a thin net margin — if heavy overhead, interest, or taxes eat the profit on the way down. That’s why reading every step beats trusting the bottom line alone."}'::jsonb),
  ('balance-sheet-and-cash-flow', 'Balance Sheet & Cash Flow', 'read', 2, 10, '{"sections":[{"text":"The balance sheet always balances on one equation: Total Assets equal what the company owes plus what its owners hold. Everything the business owns is financed either by debt or by Stockholders'' Equity — there’s no third source.","highlightedTerms":[{"term":"Stockholders'' Equity","definition":"What shareholders would receive if all assets were sold and all debts paid. Total Assets minus Total Liabilities."}]},{"text":"Two things to check on it. Liquidity: can the company cover its near-term bills, comparing current assets to current liabilities? And leverage: how much Long-Term Debt is it carrying? A little debt is normal; a lot is fragility waiting for a bad quarter.","highlightedTerms":[{"term":"Long-Term Debt","definition":"Debt that doesn''t come due for more than a year. High long-term debt can be risky if interest rates rise or the business slows."}]},{"text":"The cash flow statement exists because profit can be an illusion. A company can report a profit while its bank balance actually falls — thanks to timing and non-cash charges. Operating Cash Flow strips that away and shows the real cash thrown off by running the business.","highlightedTerms":[{"term":"Operating Cash Flow","definition":"Actual cash generated by the company''s core operations. Often considered more reliable than net income because it''s harder to manipulate."}]},{"text":"The figure many professionals trust most is Free Cash Flow — operating cash flow minus what the company spent on equipment and buildings. It’s the cash genuinely free to pay dividends, buy back shares, or pay down debt. Strong free cash flow is hard to fake.","highlightedTerms":[{"term":"Free Cash Flow","definition":"Operating cash flow minus capital expenditures. Money the company can use to pay dividends, buy back shares, or pay down debt."}]}],"funFact":"Amazon reported thin or negative net income for years while generating strong operating cash flow. The cash flow statement told a far healthier story than the income statement did."}'::jsonb),
  ('statements-quiz', 'Quick Check: Financial Statements', 'quiz', 3, 20, '{"questions":[{"question":"Which statement tells you what a company owns and owes at a single moment in time?","options":["The income statement","The balance sheet","The cash flow statement","The annual report"],"correctIndex":1,"explanation":"The balance sheet is a snapshot: assets on one side, liabilities plus equity on the other. The income and cash flow statements both cover a period of time instead."},{"question":"On the income statement, what do you get after subtracting only the direct cost of the goods from revenue?","options":["Net income","Operating income","Gross profit","Free cash flow"],"correctIndex":2,"explanation":"Revenue minus the direct cost of goods is gross profit. More costs — operating expenses, interest, taxes — are subtracted further down to reach operating and then net income."},{"question":"A company reports a healthy profit, yet its cash balance fell during the year. Which statement best explains why?","options":["The balance sheet","The income statement","The cash flow statement","None — this is impossible"],"correctIndex":2,"explanation":"Profit and cash differ because of timing and non-cash charges. The cash flow statement reconciles reported profit to the actual cash that moved."},{"question":"Free cash flow is operating cash flow minus what?","options":["Taxes","Capital expenditures — money spent on equipment and buildings","Dividends paid","Interest on debt"],"correctIndex":1,"explanation":"Free cash flow subtracts capital expenditures (spending on long-term assets) from operating cash flow — leaving the cash the company can actually put to discretionary use."}]}'::jsonb),
  ('statements-match', 'Match the Statement Lines', 'match', 4, 15, '{"pairs":[{"term":"Revenue","definition":"The top line — all sales before any costs are taken out."},{"term":"Net Income","definition":"The bottom line — profit after every cost, tax, and interest."},{"term":"Operating Income","definition":"Profit from the core business, before interest and taxes."},{"term":"Free Cash Flow","definition":"Operating cash left after spending on equipment and buildings."},{"term":"Long-Term Debt","definition":"What the company owes lenders beyond the next year."}]}'::jsonb),
  ('statements-demo', 'See It Live: A Company’s Real Numbers', 'demo', 5, 25, '{"surface":"stock-stats","ticker":"MSFT","steps":[{"id":"intro","target":"company-header","title":"From statements to a stock page","body":"The three statements you just learned aren’t abstract — BullPen distills them into the numbers on every stock page. Here is Microsoft’s.","requiredAction":"none"},{"id":"revenue","target":"stat-rev-growth","title":"Revenue growth = the top line","body":"Revenue growth comes straight off the top line of the income statement: is the company selling more each year? Rising revenue is the first sign of a growing business.","requiredAction":"none"},{"id":"margin","target":"stat-profit-margin","title":"Profit margin = the whole income statement","body":"Profit margin is the income statement in a single number — net income divided by revenue. It shows how much of every sales dollar survives all the way to the bottom line.","requiredAction":"none"},{"id":"pe","target":"stat-p-e-ttm","title":"P/E ties earnings to price","body":"The P/E ratio uses earnings per share — the bottom line, sliced per share — so it links the income statement back to what you actually pay for the stock.","requiredAction":"none"},{"id":"wrap","target":"none","title":"It all traces back to three reports","body":"Every figure here traces back to one of the three statements. Once you can read them, a page like this stops being a wall of numbers and starts telling a story.","requiredAction":"none"}]}'::jsonb),
  ('healthy-or-fragile', 'Healthy or Fragile?', 'scenario', 6, 25, '{"setup":"Two companies in the same industry. Company A has steady revenue, an 18% net margin, low debt, and free cash flow that’s comfortably positive every year. Company B has faster revenue growth and a bigger reported profit this year — but it carries heavy long-term debt, its operating cash flow is negative, and that headline profit leans on one-time accounting gains. Which is the financially healthier business?","choices":[{"label":"Company B — it’s growing faster and reported a bigger profit, so it’s clearly stronger.","feedback":"Growth and a big headline profit are seductive, but read the statements underneath. Negative operating cash flow means the business is burning cash just to run, heavy debt adds real risk, and a profit built on one-time gains won’t repeat. That’s fragility dressed up as strength.","isCorrect":false},{"label":"Company A — steady margins, low debt, and consistently positive free cash flow point to durable health.","feedback":"Exactly. You read past the headline. Genuine cash generation, a solid margin, and low debt are the marks of a business that can survive a bad year. Durable beats flashy — and the statements are how you tell them apart.","isCorrect":true},{"label":"You can’t compare them without knowing each company’s share price.","feedback":"Share price tells you valuation, not health — a different question entirely. Here you’re judging the business itself, and the three statements give you everything you need: cash flow, debt, and the quality of the earnings.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
